import { useId, useMemo, useState } from "react"
import { ArrowRight, ArrowUpRight, Check, Database, FileText, Search, ShieldCheck } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion"
import { Field, FieldDescription, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"

export type GMDLocale = "en" | "ar"
type Localized = { en: string; ar: string }
const text = (locale: GMDLocale, value: Localized) => value[locale]

export function GMDWebsiteHeader({ locale = "en", page = "home", onNavigate, onInquiry, onLocaleChange }: { locale?: GMDLocale; page?: string; onNavigate?: (page: string) => void; onInquiry?: () => void; onLocaleChange?: () => void }) {
  const links: Array<[string, Localized]> = [["about", {en:"Company",ar:"عن الشركة"}], ["services", {en:"Services",ar:"الخدمات"}], ["data", {en:"Data",ar:"البيانات"}], ["contact", {en:"Contact",ar:"تواصل"}]]
  return <header className="gmd-site-header"><a className="gmd-site-wordmark" href="?view=home" onClick={e => { e.preventDefault(); onNavigate?.("home") }}>GMD<span>.</span>GDN</a><nav aria-label={locale === "ar" ? "التنقل الرئيسي" : "Main navigation"}>{links.map(([id, label]) => <a key={id} aria-current={page === id ? "page" : undefined} href={`?view=${id}`} onClick={e => { e.preventDefault(); onNavigate?.(id) }}>{text(locale, label)}</a>)}</nav><div className="gmd-site-actions"><Button variant="outline" size="sm" onClick={() => onLocaleChange ? onLocaleChange() : window.dispatchEvent(new CustomEvent("gmd:toggle-locale"))}>{locale === "en" ? "العربية" : "English"}</Button><Button size="sm" onClick={onInquiry}>{locale === "en" ? "Start a conversation" : "ابدأ حوارًا"}<ArrowUpRight aria-hidden="true" /></Button></div></header>
}

export function GMDWebsiteFooter({ locale = "en", onNavigate }: { locale?: GMDLocale; onNavigate?: (page: string) => void }) {
  const links = [["services", "Services", "الخدمات"], ["data", "Data catalog", "فهرس البيانات"], ["about", "Company", "عن الشركة"], ["contact", "Contact", "تواصل"]] as const
  return <footer className="gmd-site-footer"><div><a className="gmd-site-wordmark" href="?view=home" onClick={e => { e.preventDefault(); onNavigate?.("home") }}>GMD<span>.</span>GDN</a><p>{locale === "en" ? "Egyptian knowledge, held with care." : "المعرفة المصرية، بعناية."}</p></div><nav aria-label={locale === "en" ? "Footer" : "روابط التذييل"}>{links.map(([id,en,ar]) => <a key={id} href={`?view=${id}`} onClick={e => { e.preventDefault(); onNavigate?.(id) }}>{locale === "en" ? en : ar}</a>)}</nav><small>© GMD · CAIRO</small></footer>
}

export function GMDEditorialHero({ locale = "en", eyebrow, title, description, image = "./assets/eg-026.jpg", actionLabel, onAction }: { locale?: GMDLocale; eyebrow: Localized; title: Localized; description: Localized; image?: string; actionLabel?: Localized; onAction?: () => void }) {
  return <section className="gmd-editorial-hero"><div className="gmd-editorial-copy"><p className="gmd-eyebrow">{text(locale, eyebrow)}</p><h1>{text(locale, title)}</h1><p className="gmd-editorial-lead">{text(locale, description)}</p>{actionLabel && <Button size="lg" onClick={onAction}>{text(locale, actionLabel)}<ArrowRight aria-hidden="true" /></Button>}</div><figure><img src={image} alt={locale === "en" ? "Archival Egyptian material from the GMD collection" : "مادة أرشيفية مصرية من مجموعة GMD"}/><figcaption>{locale === "en" ? "A collection item · source details travel with every record" : "عنصر من مجموعة · ترافق تفاصيل المصدر كل سجل"}</figcaption></figure></section>
}

const datasets = [
  {id:"film-people", type:"People & works", count:"Sample", stage:"Reference only", title:{en:"Egyptian cinema people and works",ar:"أشخاص وأعمال السينما المصرية"}, desc:{en:"A connected index of films, credits, people and release context.",ar:"فهرس مترابط للأفلام والاعتمادات والأشخاص وسياق العرض."}},
  {id:"cairo-photos", type:"Photographs", count:"Sample", stage:"Reference only", title:{en:"Cairo photographic collections",ar:"مجموعات القاهرة الفوتوغرافية"}, desc:{en:"Photographs with collection-level attribution and rights notes.",ar:"صور موثقة النسبة مع ملاحظات المجموعة والحقوق."}},
  {id:"oral-history", type:"Audio & text", count:"Sample", stage:"Reference only", title:{en:"Oral histories and transcripts",ar:"تاريخ شفهي ونصوص مفرغة"}, desc:{en:"Interview records prepared with language and contributor context.",ar:"سجلات مقابلات مرتبطة باللغة وسياق المساهمين."}},
]
export function GMDDatasetCatalog({ locale = "en", onOpenCollection }: { locale?: GMDLocale; onOpenCollection?: (id: string) => void }) {
  const [query, setQuery] = useState("")
  const filtered = useMemo(() => datasets.filter(item => `${item.id} ${item.type} ${item.title.en} ${item.title.ar}`.toLowerCase().includes(query.toLowerCase())), [query])
  return <section className="gmd-dataset-catalog"><div className="gmd-catalog-heading"><div><p className="gmd-eyebrow">{locale === "en" ? "GMD DATA / COLLECTIONS" : "بيانات GMD / المجموعات"}</p><h2>{locale === "en" ? "A catalog built around its sources." : "فهرس يبدأ من مصادره."}</h2></div><p>{locale === "en" ? "Explore sample collections and their current documentation status." : "استكشف مجموعات نموذجية وحالة توثيقها الحالية."}</p></div><label className="gmd-dataset-search"><Search aria-hidden="true"/><Input value={query} onChange={event => setQuery(event.target.value)} placeholder={locale === "en" ? "Search collections or material type" : "ابحث في المجموعات أو نوع المادة"} aria-label={locale === "en" ? "Search datasets" : "ابحث في البيانات"}/></label><div className="gmd-dataset-list">{filtered.map((item, index) => <Card key={item.id} className="gmd-dataset-card"><CardHeader><div className="gmd-dataset-meta"><span>0{index + 1} / {item.type}</span><Badge variant="outline">{item.stage}</Badge></div><CardTitle>{text(locale,item.title)}</CardTitle><CardDescription>{text(locale,item.desc)}</CardDescription></CardHeader><CardContent><span><Database aria-hidden="true"/> {item.count} {locale === "en" ? "records" : "سجلًا"}</span><span><ShieldCheck aria-hidden="true"/> {locale === "en" ? "Source notes attached" : "ملاحظات المصدر مرفقة"}</span></CardContent><CardFooter><Button variant="link" onClick={() => onOpenCollection?.(item.id)}>{locale === "en" ? "Open collection" : "افتح المجموعة"}<ArrowUpRight aria-hidden="true"/></Button></CardFooter></Card>)}{filtered.length === 0 && <p className="gmd-dataset-empty" role="status">{locale === "en" ? "No collections match this search." : "لا توجد مجموعات تطابق هذا البحث."}</p>}</div></section>
}

export function GMDProvenancePanel({ locale = "en" }: { locale?: GMDLocale }) {
  const steps = locale === "en" ? ["Contributing collection identified", "Attribution and context recorded", "Rights and reuse reviewed", "Distribution terms made visible"] : ["تحديد المجموعة المساهمة", "تسجيل النسبة والسياق", "مراجعة الحقوق وإعادة الاستخدام", "إظهار شروط التوزيع"]
  return <section className="gmd-provenance"><div><p className="gmd-eyebrow">{locale === "en" ? "SOURCE / RIGHTS / CONTEXT" : "المصدر / الحقوق / السياق"}</p><h2>{locale === "en" ? "Useful data keeps its history." : "تحتفظ البيانات المفيدة بتاريخها."}</h2><p>{locale === "en" ? "A public description, research copy and licensed dataset can each have different access rules. GMD keeps the source and permitted use legible at every handoff." : "قد تختلف قواعد الوصول بين الوصف العلني ونسخة البحث ومجموعة البيانات المرخصة. نبقي المصدر والاستخدام المسموح واضحين عند كل انتقال."}</p></div><ol>{steps.map((step,i)=><li key={step}><span>{String(i+1).padStart(2,"0")}</span><b>{step}</b>{i < steps.length - 1 && <ArrowRight aria-hidden="true"/>}</li>)}</ol></section>
}

export function GMDProcessTimeline({ locale = "en" }: { locale?: GMDLocale }) {
  const phases = locale === "en" ? [["01","Collect","Locate material and agree the contribution context."],["02","Describe","Build consistent records with human review."],["03","Connect","Relate people, works, places and themes."],["04","Distribute","Publish with source, rights and access terms." ]] : [["٠١","نجمع","نحدد المادة ونتفق على سياق المساهمة."],["٠٢","نوصف","نبني سجلات متسقة بمراجعة بشرية."],["٠٣","نربط","نصل الأشخاص والأعمال والأماكن والموضوعات."],["٠٤","نوزع","ننشر مع المصدر والحقوق وشروط الوصول."]]
  return <ol className="gmd-process-timeline">{phases.map(([n,title,desc])=><li key={n}><span>{n}</span><h3>{title}</h3><p>{desc}</p></li>)}</ol>
}

export function GMDServiceComparison({ locale = "en", onInquiry }: { locale?: GMDLocale; onInquiry?: () => void }) {
  const offerings = locale === "en" ? [{n:"01",t:"Archive & content systems",d:"Collection models, editorial workflows and public discovery."},{n:"02",t:"Research data portals",d:"Structured records, search and documented exports."},{n:"03",t:"Responsible AI datasets",d:"Permission-aware preparation, with provenance attached."}] : [{n:"٠١",t:"أنظمة الأرشيف والمحتوى",d:"نماذج للمجموعات ومسارات تحرير واكتشاف عام."},{n:"٠٢",t:"بوابات بيانات بحثية",d:"سجلات منظمة وبحث وملفات تصدير موثقة."},{n:"٠٣",t:"بيانات مسؤولة للذكاء الاصطناعي",d:"إعداد يراعي الأذونات ويحفظ المصدر."}]
  return <div className="gmd-service-comparison">{offerings.map(item=><article key={item.n}><span>{item.n} / GMD SERVICES</span><h3>{item.t}</h3><p>{item.d}</p><Button variant="link" onClick={onInquiry}>{locale === "en" ? "Discuss this service" : "ناقش هذه الخدمة"}<ArrowUpRight aria-hidden="true"/></Button></article>)}</div>
}

export function GMDEngagementOptions({ locale = "en", onInquiry }: { locale?: GMDLocale; onInquiry?: () => void }) {
  const options = locale === "en" ? [["01","Discovery scope","A focused assessment of the material, rights context and intended audience."],["02","Defined delivery","A collection, portal or publishing workflow planned around agreed outputs."],["03","Ongoing partnership","Continued editorial, data or product work as the collection grows."]] : [["٠١","استكشاف النطاق","تقييم مركز للمادة وسياق الحقوق والجمهور المقصود."],["٠٢","تسليم محدد","مجموعة أو بوابة أو مسار نشر بخطوات ومخرجات متفق عليها."],["٠٣","شراكة مستمرة","عمل تحريري أو بيانات أو منتجات مع نمو المجموعة."]]
  return <section className="gmd-engagement-options"><div><p className="gmd-eyebrow">{locale === "en" ? "SCOPE / TIMING / FEES" : "النطاق / الوقت / التكلفة"}</p><h2>{locale === "en" ? "The work sets the estimate." : "يحدد العمل تقديره."}</h2><p>{locale === "en" ? "There is no fixed public rate for unlike collections and products. We shape a written scope after understanding the material, permissions, contributors and delivery needs." : "لا يوجد سعر عام ثابت لمجموعات ومنتجات مختلفة. نحدد نطاقًا مكتوبًا بعد فهم المادة والأذونات والمساهمين ومتطلبات التسليم."}</p></div><div className="gmd-engagement-list">{options.map(([number,title,description])=><article key={number}><span>{number}</span><div><h3>{title}</h3><p>{description}</p></div><Button variant="link" onClick={onInquiry}>{locale === "en" ? "Discuss scope" : "ناقش النطاق"}<ArrowUpRight aria-hidden="true"/></Button></article>)}</div></section>
}

export function GMDContactForm({ locale = "en" }: { locale?: GMDLocale }) {
  const [submitted, setSubmitted] = useState(false)
  const [email, setEmail] = useState("")
  const [invalidFields, setInvalidFields] = useState<string[]>([])
  const formId = useId()
  if (submitted) return <div className="gmd-contact-success" role="status"><span><Check aria-hidden="true"/></span><h3>{locale === "en" ? "Your local draft is ready." : "مسودتك المحلية جاهزة."}</h3><p>{locale === "en" ? "Nothing was sent or stored. Connect this form to an approved GMD contact channel to receive inquiries." : "لم يُرسل شيء ولم يُحفظ. اربط النموذج بقناة تواصل معتمدة لدى GMD لاستقبال الاستفسارات."}</p><Button variant="outline" onClick={() => setSubmitted(false)}>{locale === "en" ? "Edit draft" : "عدّل المسودة"}</Button></div>
  return <form className="gmd-contact-form" onSubmit={event => { event.preventDefault(); const form = event.currentTarget; const invalid = [...form.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>("input:invalid,textarea:invalid")].map(control => control.name); setInvalidFields(invalid); if (form.reportValidity()) setSubmitted(true) }} noValidate><FieldGroup><Field data-invalid={invalidFields.includes("name")}><FieldLabel htmlFor={`${formId}-name`}>{locale === "en" ? "Your name" : "الاسم"}</FieldLabel><Input id={`${formId}-name`} name="name" required minLength={2} autoComplete="name" aria-invalid={invalidFields.includes("name") || undefined} onChange={() => setInvalidFields(current => current.filter(field => field !== "name"))}/></Field><Field data-invalid={invalidFields.includes("email")}><FieldLabel htmlFor={`${formId}-email`}>{locale === "en" ? "Email address" : "البريد الإلكتروني"}</FieldLabel><Input id={`${formId}-email`} name="email" type="email" required autoComplete="email" value={email} aria-invalid={invalidFields.includes("email") || undefined} onChange={event => { setEmail(event.target.value); setInvalidFields(current => current.filter(field => field !== "email")) }}/><FieldDescription>{locale === "en" ? "Used only for this local form demonstration." : "لشرح سلوك هذا النموذج المحلي فقط."}</FieldDescription></Field><Field><FieldLabel htmlFor={`${formId}-organization`}>{locale === "en" ? "Organization (optional)" : "المؤسسة (اختياري)"}</FieldLabel><Input id={`${formId}-organization`} name="organization" autoComplete="organization"/></Field><Field data-invalid={invalidFields.includes("message")}><FieldLabel htmlFor={`${formId}-message`}>{locale === "en" ? "What are you working on?" : "ما العمل الذي تستكشفه؟"}</FieldLabel><Textarea id={`${formId}-message`} name="message" required minLength={12} rows={5} aria-invalid={invalidFields.includes("message") || undefined} onChange={() => setInvalidFields(current => current.filter(field => field !== "message"))}/></Field></FieldGroup><p className="gmd-form-notice"><FileText aria-hidden="true"/>{locale === "en" ? "Local demonstration · no message is sent or saved." : "نموذج محلي · لا يُرسل أو يُحفظ أي محتوى."}</p><Button type="submit">{locale === "en" ? "Review inquiry" : "راجع الاستفسار"}<ArrowUpRight aria-hidden="true"/></Button></form>
}

export function GMDProjectFAQ({ locale = "en" }: { locale?: GMDLocale }) {
  return <Accordion type="single" collapsible className="gmd-project-faq"><AccordionItem value="ownership"><AccordionTrigger>{locale === "en" ? "Does digitizing an archive change its rights?" : "هل يغيّر تحويل الأرشيف رقميًا حقوقه؟"}</AccordionTrigger><AccordionContent>{locale === "en" ? "No. Digitization and public visibility do not grant reuse permission. Rights are reviewed and displayed separately for each collection and use." : "لا. الرقمنة والإتاحة العامة لا تمنحان إذن إعادة الاستخدام. تُراجع الحقوق وتُعرض بشكل مستقل لكل مجموعة واستخدام."}</AccordionContent></AccordionItem><AccordionItem value="sources"><AccordionTrigger>{locale === "en" ? "How does GMD document sources?" : "كيف توثق GMD المصادر؟"}</AccordionTrigger><AccordionContent>{locale === "en" ? "Records retain their contributing collection, known attribution, editorial notes and available rights context. Unknown details remain explicitly unknown." : "تحتفظ السجلات بالمجموعة المساهمة والنسبة المعروفة والملاحظات التحريرية وسياق الحقوق المتاح. وتظل التفاصيل المجهولة موضحة بصفتها مجهولة."}</AccordionContent></AccordionItem><AccordionItem value="formats"><AccordionTrigger>{locale === "en" ? "Can a collection be prepared for different audiences?" : "هل يمكن إعداد المجموعة لجماهير مختلفة؟"}</AccordionTrigger><AccordionContent>{locale === "en" ? "Yes. Public browsing, research access and licensed data products can use different fields, permissions and delivery formats." : "نعم. يمكن أن تختلف الحقول والأذونات وصيغ التسليم بين التصفح العام والوصول البحثي ومنتجات البيانات المرخصة."}</AccordionContent></AccordionItem></Accordion>
}
